import { useCallback, useEffect, useState } from "react";

import { api, type BinderState, type SpinePaperState, type SpinePapersStatus } from "../api";
import { href } from "../router";
import { useAction } from "../useAction";

// Papers the Financial Spine produces (spec 3A "lead schedule per area, tying to the Financial
// Spine", 3C "every lead schedule, and the adjustment chain"; Stage E, D32). One lead schedule
// per mapped area and one adjustment chain per binder, generated by a person from the binder's
// linked, locked Spine version and signed off by the ordinary chain. Every state and every
// reason here is the backend's, shown as it was said.

export const STATE_LABEL: Record<SpinePaperState, string> = {
  none: "not generated",
  current: "current",
  stale: "stale",
  not_checked: "not checked",
};

export function StateBadge({ state, detail }: { state: SpinePaperState; detail: string | null }) {
  const tone =
    state === "current"
      ? "bg-green-50 text-green-800"
      : state === "stale"
        ? "bg-amber-50 text-amber-900"
        : state === "not_checked"
          ? "bg-slate-100 text-slate-600"
          : "bg-white text-slate-500 border border-slate-200";
  return (
    <span className="inline-flex flex-wrap items-baseline gap-1">
      <span className={`rounded px-1.5 py-0.5 text-xs ${tone}`} data-testid="spine-paper-state">
        {STATE_LABEL[state]}
      </span>
      {detail && (
        <span className="text-xs text-slate-600" data-testid="spine-paper-detail">
          {detail}
        </span>
      )}
    </span>
  );
}

export function SpinePapersCard({
  binderId,
  state,
  onChanged,
  refreshKey = "",
}: {
  binderId: string;
  state: BinderState;
  onChanged: () => Promise<void>;
  // Changes when the binder's Spine link or state changes, so the card refetches its status
  // (the link is saved by another card on the same screen).
  refreshKey?: string;
}) {
  const [status, setStatus] = useState<SpinePapersStatus | null>(null);
  const [readError, setReadError] = useState<string | null>(null);

  const load = useCallback(async () => {
    setStatus(await api.getSpinePapers(binderId));
    await onChanged();
  }, [binderId, onChanged]);
  const { run, busy, error } = useAction(load);
  useEffect(() => {
    api
      .getSpinePapers(binderId)
      .then(setStatus)
      .catch((e: Error) => setReadError(e.message));
  }, [binderId, refreshKey]);

  if (readError) {
    return (
      <section className="rounded border border-slate-200 bg-white p-4" data-testid="spine-papers-card">
        <h2 className="text-lg font-semibold">Spine papers</h2>
        <p className="mt-1 text-sm text-slate-500">Spine papers could not be read: {readError}</p>
      </section>
    );
  }
  if (!status) return <section className="text-sm text-slate-500">Loading Spine papers…</section>;

  const open = state === "open";
  const button =
    "rounded border border-slate-300 px-3 py-1.5 text-sm hover:bg-slate-100 disabled:opacity-50";
  const small = "rounded border border-slate-300 px-2 py-0.5 text-xs hover:bg-slate-100 disabled:opacity-50";
  const shown = status.areas.filter((a) => a.mapped || a.state !== "none");
  const unmapped = status.areas.filter((a) => !a.mapped && a.state === "none").map((a) => a.code);
  const pending = shown.filter((a) => a.mapped && a.state === "none");
  const canGenerate = open && status.can_generate && !busy;

  return (
    <section className="rounded border border-slate-200 bg-white p-4" data-testid="spine-papers-card">
      <h2 className="text-lg font-semibold">Spine papers</h2>
      <p className="mt-1 text-sm text-slate-600">
        Lead schedules per area and the adjustment chain, built from the binder&apos;s linked, locked
        Spine version. Figures are the Spine&apos;s; a person prepares, reviews and signs off.
      </p>
      {status.version_id && (
        <p className="mt-1 text-xs text-slate-500" data-testid="spine-papers-version">
          Linked version {status.version_label} <code className="font-mono">{status.version_id}</code>
          {status.version_hash && (
            <>
              {" "}
              hash <code className="font-mono">{status.version_hash.slice(0, 12)}…</code>
            </>
          )}
        </p>
      )}
      {status.reason && (
        <p className="mt-2 rounded bg-amber-50 px-3 py-2 text-sm text-amber-900" data-testid="spine-papers-reason">
          Lead schedules cannot be generated: {status.reason}
        </p>
      )}
      {status.map_source === "derived" && (
        <p className="mt-2 text-xs text-slate-600" data-testid="spine-papers-derived">
          This template has no area map, so the areas are derived from the Spine&apos;s Schedule III
          tree (D38): one area per statement-level head group, named as the Spine names it. A map
          entered in the template replaces this.
          {status.beyond_letters.length > 0 && (
            <>
              {" "}
              {status.beyond_letters.length} head group(s) had no letter D–T left:{" "}
              {status.beyond_letters.join(", ")}.
            </>
          )}
        </p>
      )}
      {status.map_problems.length > 0 && (
        <ul className="mt-2 list-disc pl-5 text-sm text-red-800" data-testid="spine-papers-problems">
          {status.map_problems.map((p) => (
            <li key={p}>{p}</li>
          ))}
        </ul>
      )}
      {error && (
        <p role="alert" className="mt-2 text-sm text-red-700">
          {error}
        </p>
      )}

      <h3 className="mt-3 font-medium">Lead schedules by area</h3>
      {shown.length === 0 ? (
        <p className="mt-1 text-sm text-slate-500" data-testid="spine-papers-no-areas">
          No area has Schedule III heads: the template has no area map and nothing could be derived
          from the Spine&apos;s tree (D38), so no lead schedule can be generated (TEMPLATE_AUTHORING item 1).
        </p>
      ) : (
        <ul className="mt-1 divide-y divide-slate-100 text-sm">
          {shown.map((a) => (
            <li key={a.code} className="flex flex-wrap items-baseline justify-between gap-2 py-1.5" data-testid="spine-area">
              <span>
                <span className="font-mono">{a.code}</span> {a.name}
                {!a.mapped && <span className="ml-2 text-xs text-slate-500">no heads in the area map</span>}
              </span>
              <span className="flex flex-wrap items-baseline gap-2">
                {a.paper_id ? (
                  <a href={href({ name: "paper", id: a.paper_id })} className="font-mono underline">
                    {a.ref}
                  </a>
                ) : (
                  <span className="font-mono text-slate-400">{a.ref}</span>
                )}
                <StateBadge state={a.state} detail={a.detail} />
                {a.mapped && a.state === "none" && open && (
                  <button
                    type="button"
                    disabled={!canGenerate}
                    onClick={() => void run(() => api.generateLeadSchedules(binderId, [a.code]))}
                    className={small}
                  >
                    Generate {a.code}-L
                  </button>
                )}
              </span>
            </li>
          ))}
        </ul>
      )}
      {unmapped.length > 0 && shown.length > 0 && (
        <p className="mt-1 text-xs text-slate-500" data-testid="spine-papers-unmapped">
          {unmapped.length} area(s) have no heads in the area map: {unmapped.join(", ")}.
        </p>
      )}
      {status.unassigned_heads.length > 0 && (
        <p className="mt-1 text-xs text-slate-500" data-testid="spine-papers-unassigned">
          Mappable heads in no area: {status.unassigned_heads.join(", ")}.
        </p>
      )}
      {open && pending.length > 0 && (
        <button
          type="button"
          disabled={!canGenerate}
          onClick={() => void run(() => api.generateLeadSchedules(binderId, null))}
          className={`mt-2 ${button}`}
        >
          Generate lead schedules ({pending.length})
        </button>
      )}

      <h3 className="mt-4 font-medium">Adjustment chain</h3>
      <div className="mt-1 flex flex-wrap items-baseline gap-2 text-sm" data-testid="spine-chain">
        {status.chain.paper_id ? (
          <a href={href({ name: "paper", id: status.chain.paper_id })} className="font-mono underline">
            {status.chain.ref}
          </a>
        ) : (
          <span className="font-mono text-slate-400">{status.chain.ref}</span>
        )}
        <span className="text-slate-500">section {status.chain.section}</span>
        <StateBadge state={status.chain.state} detail={status.chain.detail} />
        {open && status.chain.state === "none" && (
          <button
            type="button"
            disabled={!status.chain.can_generate || busy}
            onClick={() => void run(() => api.generateAdjustmentChain(binderId))}
            className={small}
          >
            Generate adjustment chain
          </button>
        )}
      </div>
      {status.chain.reason && status.chain.state === "none" && (
        <p className="mt-1 text-xs text-amber-900" data-testid="spine-chain-reason">
          {status.chain.reason}
        </p>
      )}
      {!open && (
        <p className="mt-3 text-xs text-slate-500">
          The binder is {state}: Spine papers are generated and regenerated while it is open. A stale
          paper is information in the assembly status, never a blocker.
        </p>
      )}
      {busy && <p className="mt-2 text-sm text-slate-600">Working…</p>}
    </section>
  );
}
